<script setup>
import { onMounted, ref } from 'vue'
import { api, errorMessage } from '../api'
const orders=ref([]), sessions=ref([]), error=ref('')
const money=v=>`${Number(v||0).toLocaleString('vi-VN')}₫`
onMounted(async()=>{try{const [o,s]=await Promise.all([api.get('/api/pos/orders'),api.get('/api/pos/sessions')]);orders.value=o.data;sessions.value=s.data}catch(e){error.value=errorMessage(e)}})
</script>
<template><div class="view-wrap"><div class="view-heading"><div><span class="eyebrow">FREEDOMS / STAFF WORKSPACE</span><h1>Tổng quan nhân viên</h1><p>Trung tâm thao tác bán hàng, theo dõi đơn POS và xử lý sau bán của tài khoản nhân viên đang đăng nhập.</p></div><RouterLink to="/employee/pos" class="btn btn-primary">Mở POS</RouterLink></div><p v-if="error" class="notice notice-error">{{error}}</p><div class="stats-grid"><div class="stat-card"><small>Đơn POS của tôi</small><strong>{{orders.length}}</strong><span>Đơn đã lập tại quầy</span></div><div class="stat-card"><small>Hóa đơn / phiên chờ</small><strong>{{sessions.length}}</strong><span>Phiên bán chưa chốt</span></div><div class="stat-card"><small>Đơn đã hoàn thành</small><strong>{{orders.filter(x=>x.status==='COMPLETED').length}}</strong><span>Thanh toán đã xác nhận</span></div></div><section class="surface-card"><h2>Thao tác nhanh</h2><div class="dashboard-quick-grid"><RouterLink to="/employee/pos" class="quick-card"><span>▣</span><b>Bán hàng tại quầy</b><small>Tạo phiên bán, chọn khách, giữ hóa đơn và thanh toán.</small></RouterLink><RouterLink to="/employee/held" class="quick-card"><span>◷</span><b>Hóa đơn chờ</b><small>Tiếp tục hoặc hủy phiên bán chưa chốt.</small></RouterLink><RouterLink to="/employee/orders" class="quick-card"><span>▤</span><b>Đơn hàng & thanh toán</b><small>Xem đơn POS, xác nhận tiền vào và gửi yêu cầu hoàn tiền.</small></RouterLink><RouterLink to="/employee/customers" class="quick-card"><span>♙</span><b>Khách hàng</b><small>Tìm kiếm hạng thành viên, thông tin và địa chỉ mặc định.</small></RouterLink><RouterLink to="/employee/refunds" class="quick-card"><span>↩</span><b>Yêu cầu hoàn tiền</b><small>Theo dõi thao tác hoàn tiền của cửa hàng.</small></RouterLink></div></section><section class="surface-card"><h2>Đơn POS gần đây</h2><div v-for="o in orders.slice(0,5)" :key="o.id" class="employee-recent-row"><div><b>{{o.code}}</b><small>{{o.customerName}} · {{new Date(o.createdAt).toLocaleString('vi-VN')}}</small></div><strong>{{money(o.totalAmount)}}</strong><span class="status-pill" :class="'status-'+String(o.status).toLowerCase()">{{o.status}}</span></div><p v-if="!orders.length" class="empty-state">Chưa có đơn POS.</p></section></div></template>
